    /** English name for a Lost Cities asset name, or "" when the modpack has none. */
    static String english(String asset) {
        String[] row = row(asset);
        return row == null ? "" : row[1];
    }

    /** Chinese name for a Lost Cities asset name: the handwritten table first, then a rough gloss. */
    static String chinese(String asset) {
        String[] row = row(asset);
        if (row != null) {
            return row[2];
        }
        return gloss(asset);
    }

    /**
     * 词根拼名：整合包里 535 种楼只写了 107 个中文名，剩下的（例如 {@code building_apartmentsmalla}）
     * 按认识的词根拼一个大概的名字。拼不出来就返回空，调用方据此说「没有中文名」而不是编一个。
     */
    static String gloss(String asset) {
        String fam = family(asset);
        if (fam.isEmpty()) {
            return "";
        }
        String body = fam;
        for (String head : new String[] {"building_", "multi_", "highrise_", "district_"}) {
            if (body.startsWith(head)) {
                body = body.substring(head.length());
                break;
            }
        }
        if (body.isEmpty()) {
            return "";
        }
        String variant = "";
        int last = body.length() - 1;
        if (last > 1 && (body.charAt(last) == '_')) {
            body = body.substring(0, last);
            last = body.length() - 1;
        }
        if (last > 1 && Character.isLetterOrDigit(body.charAt(last))
                && "abcdefgh12345".indexOf(body.charAt(last)) >= 0
                && !Character.isDigit(body.charAt(last - 1))) {
            char c = body.charAt(last);
            variant = Character.isDigit(c) ? String.valueOf(c) : String.valueOf(Character.toUpperCase(c));
            body = body.substring(0, last);
        }
        StringBuilder cn = new StringBuilder();
        for (String[] pair : GLOSS) {
            if (body.contains(pair[0])) {
                cn.append(pair[1]);
            }
        }
        if (cn.length() == 0) {
            return "";
        }
        return variant.isEmpty() ? cn.toString() : variant + "型" + cn;
    }

