    private static String[] row(String asset) {
        if (asset == null || asset.isEmpty()) {
            return null;
        }
        String fam = family(asset);
        for (int i = 0; i + 2 < DATA.length; i += 3) {
            if (DATA[i].equals(fam)) {
                return new String[] {DATA[i], DATA[i + 1], DATA[i + 2]};
            }
        }
        return null;
    }

    /** Strips rotation suffixes and multi-building chunk indices, so all parts share a name. */
    static String family(String asset) {
        String s = asset;
        // at() 报的是 "deceasedcraft:building_office1a/building_office1a"（带命名空间、带 /part），
        // 以前整串拿去查表，于是一栋明明有中文名的楼也报 name_cn = ""。
        int colon = s.indexOf(':');
        if (colon >= 0) {
            s = s.substring(colon + 1);
        }
        int slash = s.indexOf('/');
        if (slash >= 0) {
            s = s.substring(0, slash);
        }
        if (s.endsWith("_90") || s.endsWith("_180") || s.endsWith("_270")) {
            s = s.substring(0, s.lastIndexOf('_'));
        }
        if (s.startsWith("multi_")) {
            int cut = s.length();
            while (cut > 0 && Character.isDigit(s.charAt(cut - 1))) {
                cut--;
            }
            if (cut < s.length() && cut > 0 && s.charAt(cut - 1) == '_') {
                s = s.substring(0, cut - 1);
            }
        }
        return s;
    }
